const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('latin1');
// Find all user records with Emma
const regex = /user_[a-f0-9]+/g;
let match;
const users = new Set();
while ((match = regex.exec(text)) !== null) {
  users.add(match[0]);
}
// For each user, check if Emma Chen appears nearby
for (const uid of users) {
  let idx = 0;
  while ((idx = text.indexOf(uid, idx)) !== -1) {
    const start = Math.max(0, idx - 50);
    const end = Math.min(text.length, idx + 200);
    const snippet = text.substring(start, end);
    if (snippet.includes('Emma Chen')) {
      console.log(uid, '-> Emma Chen found');
      // print context
      let clean = '';
      for (let i = start; i < end; i++) {
        const c = buf[i];
        if (c >= 32 && c < 127) clean += String.fromCharCode(c);
        else clean += '.';
      }
      console.log(clean);
      console.log('---');
    }
    idx += uid.length;
  }
}
